CREATE VIEW std_ps5_inventory AS SELECT CAST("IGDB ID" AS BIGINT) AS igdb_id, CAST(OpenCritic_ID AS BIGINT) AS opencritic_id, main."trim"(Title) AS game_title, Genre AS genre_raw, Theme AS theme_raw, "Mode" AS mode_raw, Perspective AS perspective_raw, "nullif"(main."trim"("Source"), 'N/A') AS acquisition_source_raw, "nullif"(main."trim"("File Location"), 'N/A') AS storage_location_raw, "nullif"(main."trim"(Status), 'N/A') AS play_status_raw, CAST("Owned?" AS BOOLEAN) AS owned_flag, TRY_CAST("Difficulty (1–5)" AS DECIMAL(3,2)) AS difficulty_rating, TRY_CAST("Base Length (hrs)" AS DECIMAL(8,2)) AS base_length_hours, CASE  WHEN ((main."trim"("Game Length (hrs)") = '0 h,  00 m')) THEN (NULL) ELSE TRY_CAST("Game Length (hrs)" AS DECIMAL(8,2)) END AS full_completion_hours, TRY_CAST("File Size (GB)" AS DECIMAL(10,2)) AS file_size_gb, 'PS5' AS platform_name FROM stg_ps5_inventory;
